cards.css:
.card {
    font-family: arial;
    font-size: 20px;
    text-align: center;
    color: black;
    background-color: white;
}

.cloze {
 font-weight: bold;
 color: blue;
}
.nightMode .cloze {
 color: lightblue;
}



.sent { display: none; }
.sent:has(.cloze) { display: block; }
.sent .en { display: block; font-size: 0.8em; color: #777; font-style: italic; margin-top: 8px; }
.audio-row { text-align: center; margin: 10px 0 1.2em; }
.example { margin-top: 4px; font-size: 0.85em; }

